    <title>Support Contact Form</title>
    <style>
        :root {
            --primary-color: #2563eb;
            --primary-hover: #1d4ed8;
            --text-color: #1f2937;
            --text-muted: #6b7280;
            --border-color: #d1d5db;
            --focus-ring: rgba(37, 99, 235, 0.2);
            --error-color: #dc2626;
            --bg-color: #f9fafb;
            --card-bg: #ffffff;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
            background-color: var(--bg-color);
            color: var(--text-color);
            line-height: 1.5;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 1rem;
        }

        .container {
            width: 100%;
            max-width: 480px;
            background-color: var(--card-bg);
            padding: 2rem;
            border-radius: 0.75rem;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
        }

        h1 {
            font-size: 1.5rem;
            font-weight: 700;
            margin-bottom: 0.5rem;
            color: var(--text-color);
        }

        p.description {
            color: var(--text-muted);
            margin-bottom: 2rem;
            font-size: 0.875rem;
        }

        .form-field {
            margin-bottom: 1.5rem;
        }

        label {
            display: block;
            font-size: 0.875rem;
            font-weight: 600;
            margin-bottom: 0.5rem;
        }

        label [aria-hidden="true"] {
            color: var(--error-color);
            margin-left: 0.125rem;
        }

        input {
            width: 100%;
            padding: 0.625rem 0.75rem;
            font-size: 1rem;
            border: 1px solid var(--border-color);
            border-radius: 0.375rem;
            transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
            background-color: #fff;
        }

        input:focus {
            outline: none;
            border-color: var(--primary-color);
            box-shadow: 0 0 0 3px var(--focus-ring);
        }

        .help-text {
            font-size: 0.75rem;
            color: var(--text-muted);
            margin-top: 0.375rem;
        }

        button[type="submit"] {
            width: 100%;
            background-color: var(--primary-color);
            color: white;
            padding: 0.75rem 1rem;
            font-size: 1rem;
            font-weight: 600;
            border: none;
            border-radius: 0.375rem;
            cursor: pointer;
            transition: background-color 0.15s ease-in-out;
            margin-top: 1rem;
        }

        button[type="submit"]:hover {
            background-color: var(--primary-hover);
        }

        button[type="submit"]:focus {
            outline: 2px solid transparent;
            outline-offset: 2px;
            box-shadow: 0 0 0 3px var(--focus-ring);
        }

        .sr-only {
            position: absolute;
            width: 1px;
            height: 1px;
            padding: 0;
            margin: -1px;
            overflow: hidden;
            clip: rect(0, 0, 0, 0);
            white-space: nowrap;
            border-width: 0;
        }
    </style>
</head>
<body>
    <main class="container">
        <h1>Contact Support</h1>
        <p class="description">Please fill out the form below and we'll get back to you as soon as possible.</p>

        <div id="root"></div>
    </main>

    <script>
        // React-style component structure
        function FormField({ id, label, required, helpText, children }) {
            const labelEl = document.createElement('label');
            labelEl.setAttribute('for', id);
            labelEl.textContent = label;

            if (required) {
                const asterisk = document.createElement('span');
                asterisk.setAttribute('aria-hidden', 'true');
                asterisk.textContent = ' *';
                labelEl.appendChild(asterisk);
            }

            const fieldDiv = document.createElement('div');
            fieldDiv.className = 'form-field';
            fieldDiv.appendChild(labelEl);
            fieldDiv.appendChild(children);

            if (helpText) {
                const helpEl = document.createElement('p');
                helpEl.id = `${id}-help`;
                helpEl.className = 'help-text';
                helpEl.textContent = helpText;
                fieldDiv.appendChild(helpEl);
                children.setAttribute('aria-describedby', helpEl.id);
            }

            return fieldDiv;
        }

        function Input({ id, type, name, required, autocomplete, placeholder }) {
            const input = document.createElement('input');
            input.id = id;
            input.type = type;
            input.name = name;
            input.required = required;
            if (autocomplete) input.autocomplete = autocomplete;
            if (placeholder) input.placeholder = placeholder;
            return input;
        }

        function App() {
            const form = document.createElement('form');
            form.noValidate = true; // Handle validation manually if needed, but requirements say no inline validation on initial render

            const nameField = FormField({
                id: 'full-name',
                label: 'Full Name',
                required: true,
                children: Input({
                    id: 'full-name',
                    type: 'text',
                    name: 'name',
                    required: true,
                    autocomplete: 'name'
                })
            });

            const emailField = FormField({
                id: 'email-address',
                label: 'Email Address',
                required: true,
                children: Input({
                    id: 'email-address',
                    type: 'email',
                    name: 'email',
                    required: true,
                    autocomplete: 'email'
                })
            });

            const phoneField = FormField({
                id: 'phone-number',
                label: 'Phone Number',
                required: false,
                helpText: 'Expected format: (555) 555-5555',
                children: Input({
                    id: 'phone-number',
                    type: 'tel',
                    name: 'phone',
                    required: false,
                    autocomplete: 'tel'
                })
            });

            const submitBtn = document.createElement('button');
            submitBtn.type = 'submit';
            submitBtn.textContent = 'Submit';

            form.appendChild(nameField);
            form.appendChild(emailField);
            form.appendChild(phoneField);
            form.appendChild(submitBtn);

            form.addEventListener('submit', (e) => {
                e.preventDefault();
                alert('Form submitted successfully!');
            });

            return form;
        }

        // Render the app
        const root = document.getElementById('root');
        root.appendChild(App());
    </script>
</body>
</html>
