                label: 'Phone Number',
                required: false,
                helpText: 'Expected format: (555) 555-5555',
                children: Input({
                    id: 'phone-number',
                    type: 'tel',
                    name: 'phone',
                    required: false,
                    autocomplete: 'tel'
                })
            });

