+        children: Input({
+            id: 'full-name',
+            type: 'text',
+            name: 'name',
+            required: true,
+            autocomplete: 'name'
+        })
+    });
+
+    const emailField = FormField({
+        id: 'email-address',
+        label: 'Email Address',
+        required: true,
+        children: Input({
