 * FormField Component
 * Renders a label, the input field, and optional help text.
 */
function FormField({ id, label, required, helpText, children }) {
    const fieldDiv = document.createElement('div');
    fieldDiv.className = 'form-field';

    const labelEl = document.createElement('label');
    labelEl.setAttribute('for', id);
    labelEl.textContent = label;

    if (required) {
        const asterisk = document.createElement('span');
        asterisk.setAttribute('aria-hidden', 'true');
        asterisk.textContent = ' *';
        labelEl.appendChild(asterisk);
    }

    fieldDiv.appendChild(labelEl);
    fieldDiv.appendChild(children);

    if (helpText) {
        const helpEl = document.createElement('p');
        helpEl.id = `${id}-help`;
        helpEl.className = 'help-text';
        helpEl.textContent = helpText;
        fieldDiv.appendChild(helpEl);
        children.setAttribute('aria-describedby', helpEl.id);
    }

    return fieldDiv;
}

/**
 * Input Component
 * Renders a basic input element with necessary accessibility attributes.
 */
function Input({ id, type, name, required, autocomplete, placeholder }) {
    const input = document.createElement('input');
    input.id = id;
    input.type = type;
    input.name = name;
    input.required = !!required;
    if (autocomplete) input.autocomplete = autocomplete;
    if (placeholder) input.placeholder = placeholder;
    return input;
}

/**
 * ContactForm Component
 * Composes the fields and handles submission.
 */
function ContactForm() {
    const form = document.createElement('form');
    // Inline validation is not shown on initial render per requirements.
    // Using novalidate to prevent default browser tooltips if we wanted custom ones,
    // but the prompt just says "Do not show inline validation messages on initial render".
    form.noValidate = false; 

    const nameField = FormField({
        id: 'full-name',
        label: 'Full Name',
        required: true,
        children: Input({
            id: 'full-name',
            type: 'text',
            name: 'name',
            required: true,
            autocomplete: 'name'
        })
    });

    const emailField = FormField({
        id: 'email-address',
        label: 'Email Address',
        required: true,
        children: Input({
            id: 'email-address',
            type: 'email',
            name: 'email',
            required: true,
            autocomplete: 'email'
        })
    });

    const phoneField = FormField({
        id: 'phone-number',
        label: 'Phone Number',
        required: false,
        helpText: 'Expected format: (555) 555-5555',
        children: Input({
            id: 'phone-number',
            type: 'tel',
            name: 'phone',
            required: false,
            autocomplete: 'tel'
        })
    });

    const submitBtn = document.createElement('button');
    submitBtn.type = 'submit';
    submitBtn.textContent = 'Submit';

    form.appendChild(nameField);
    form.appendChild(emailField);
    form.appendChild(phoneField);
    form.appendChild(submitBtn);

    form.addEventListener('submit', (e) => {
        // Native validation will trigger if noValidate is false.
        // If it passes:
        if (form.checkValidity()) {
            e.preventDefault();
            alert('Thank you! Your support request has been submitted.');
            form.reset();
        }
    });

    return form;
}

/**
 * App Entry Point
 */
function App() {
    const container = document.createElement('div');
    container.appendChild(ContactForm());
    return container;
}

// Render the application
document.addEventListener('DOMContentLoaded', () => {
    const root = document.getElementById('root');
    if (root) {
        root.appendChild(App());
    }
});
