         id: 'email-address',
         label: 'Email Address',
         required: true,
         children: Input({
             id: 'email-address',
             type: 'email',
             name: 'email',
             required: true,
             autocomplete: 'email'
         })
     });

     const phoneField = FormField({
         id: 'phone-number',
         label: 'Phone Number',
         required: false,
         helpText: 'Expected format: (555) 555-5555',
         children: Input({
             id: 'phone-number',
             type: 'tel',
             name: 'phone',
             required: false,
             autocomplete: 'tel'
